function [smooth_path, raw_path, is_success] = ThetaStarPlanner(start_pt, goal_pt, map_data)
    % THETASTARPLANNER Theta* Any-Angle Path Planner (Drop-In Replacement for AStarPlanner)
    %
    % Uses the Theta* algorithm to produce shorter, any-angle paths compared
    % to grid-constrained A*. The line-of-sight parent rewiring eliminates
    % unnecessary intermediate waypoints automatically.
    %
    % Inputs:
    %   start_pt - [x_start, y_start] in world coordinates [m]
    %   goal_pt  - [x_goal, y_goal]   in world coordinates [m]
    %   map_data - struct generated by build_map.m
    %
    % Outputs:
    %   smooth_path - [N_wp x 2] Any-angle waypoint sequence (world coords)
    %   raw_path    - [N_raw x 2] Same as smooth_path (Theta* is inherently smooth)
    %   is_success  - Boolean flag

    grid_map = map_data.grid_map;
    x_vec = map_data.x_vec;
    y_vec = map_data.y_vec;
    res = map_data.resolution;

    [Ny, Nx] = size(grid_map);

    %% 1. CONVERT WORLD COORDINATES TO GRID [row, col] FOR theta_star()
    start_col = max(min(round((start_pt(1) - x_vec(1)) / res) + 1, Nx), 1);
    start_row = max(min(round((start_pt(2) - y_vec(1)) / res) + 1, Ny), 1);

    goal_col = max(min(round((goal_pt(1) - x_vec(1)) / res) + 1, Nx), 1);
    goal_row = max(min(round((goal_pt(2) - y_vec(1)) / res) + 1, Ny), 1);

    % Ensure start and goal are in free cells; if not, find nearest free cell
    if grid_map(start_row, start_col) ~= 0
        [start_row, start_col] = find_nearest_free(grid_map, start_row, start_col);
    end
    if grid_map(goal_row, goal_col) ~= 0
        [goal_row, goal_col] = find_nearest_free(grid_map, goal_row, goal_col);
    end

    %% 2. RUN THETA* ALGORITHM
    grid_path = theta_star(grid_map, [start_row, start_col], [goal_row, goal_col]);

    %% 3. CONVERT GRID PATH BACK TO WORLD COORDINATES
    if ~isempty(grid_path)
        is_success = true;
        N_pts = size(grid_path, 1);
        world_path = zeros(N_pts, 2);
        for k = 1:N_pts
            r = grid_path(k, 1);  % row
            c = grid_path(k, 2);  % col
            world_path(k, 1) = x_vec(min(max(c, 1), Nx));  % x from column
            world_path(k, 2) = y_vec(min(max(r, 1), Ny));  % y from row
        end

        % Theta* already produces any-angle paths, so smooth = raw
        raw_path    = world_path;
        smooth_path = world_path;
    else
        % Fallback: direct line if Theta* fails
        is_success  = false;
        raw_path    = [start_pt(:)'; goal_pt(:)'];
        smooth_path = raw_path;
        warning('ThetaStarPlanner: No path found, falling back to direct line.');
    end
end

function [fr, fc] = find_nearest_free(grid_map, r, c)
    % Searches outward in a spiral to find the nearest free cell
    [Ny, Nx] = size(grid_map);
    for radius = 1:max(Ny, Nx)
        for dr = -radius:radius
            for dc = -radius:radius
                nr = r + dr;
                nc = c + dc;
                if nr >= 1 && nr <= Ny && nc >= 1 && nc <= Nx
                    if grid_map(nr, nc) == 0
                        fr = nr;
                        fc = nc;
                        return;
                    end
                end
            end
        end
    end
    fr = r;
    fc = c;
end
